# يبني questions/madar-penal-territoriality.json من أسئلة الملف الأصلي (_raw_questions.json)
# + جدول الإجابات أدناه. الإجابات مستنتجة من نص الشرح نفسه وتحتاج مراجعة المؤلف (answerStatus).
# كل مرساة تُفحص: يجب أن تظهر مرة واحدة بالضبط في نص الكتاب بعد التطبيع.
import json, re, sys
ROOT = sys.argv[1] if len(sys.argv) > 1 else '.'
def norm(s):
    s = re.sub('[\u064B-\u0670\u0640]', '', str(s or ''))
    s = re.sub('[أإآٱ]', 'ا', s); s = s.replace('ى', 'ي').replace('ة', 'ه')
    s = re.sub(r'[^\u0600-\u06FFa-zA-Z0-9\s]', ' ', s)
    return re.sub(r'\s+', ' ', s).strip().lower()
def btext(b):
    h = ' '.join(b.get('items', [])) if b['t'] in ('ul', 'ol') else (b.get('l', '') + ' ' + b.get('h', '') if b['t'] == 'co' else b.get('h', ''))
    return norm(re.sub(r'<[^>]+>', ' ', h))
book = json.load(open(ROOT + '/books/madar-penal-territoriality.json', encoding='utf8'))
blocks = [b for p in book['structure']['parts'] for s in p['sections'] for c in s['chapters'] for u in c['subsections'] for b in u['paragraphs']]
raw = json.load(open(ROOT + '/tools/_raw_questions.json', encoding='utf8'))
# n: (الإجابة، المبدأ، المرساة، التفسير)  — الإجابة: فهرس الخيار (صح=0، خطأ=1، نعم=0، لا=1)
K = {
 1: (0, 'مكان وقوع الجريمة', 'لا عبرة بالأعمال التحضيرية', 'لا عبرة بالأعمال التحضيرية في تحديد مكان الجريمة؛ أما النشاط (الطعن) والنتيجة (الوفاة) فيقع بكل منهما جزء من الجريمة في الإقليم.'),
 2: (0, 'أثر الحكم الأجنبي', 'لا يجوز إقامة الدعوى الجنائية على من ثبت أن المحاكم الأجنبية برأته', 'م4/2: البراءة النهائية، أو الإدانة النهائية مع استيفاء العقوبة، تمنع إقامة الدعوى، ويرد على ذلك استثناءان: العينية والعالمية.'),
 3: (1, 'إقليم الدولة', 'ولا يتجاوز عرض البحر الإقليمي 12 ميلا بحريا', 'عرض البحر الإقليمي لا يتجاوز 12 ميلًا بحريًا (اتفاقية قانون البحار 1982، م3).'),
 4: (0, 'مبدأ العالمية', 'لا يلزم أن يعاقب القانون الأجنبي على الفعل', 'من ضوابط العالمية: لا أثر لجنسية الفاعل، ولا يلزم أن يعاقب القانون الأجنبي على الفعل.'),
 5: (0, 'مبدأ جنسية الطائرة', 'يحكم الجريمة على متن الطائرة قانون الدولة التي تحمل الطائرة جنسيتها', 'يحكم الجريمة على متن الطائرة قانون الدولة التي تحمل جنسيتها (اتفاقية طوكيو 1963).'),
 6: (0, 'الشخصية الإيجابية', 'يلاحق القانون الوطني مواطنه على جريمة ارتكبها كلها في الخارج', 'الشخصية الإيجابية: يلاحق القانون الوطني مواطنه على جريمة ارتكبها كلها في الخارج.'),
 7: (1, 'إقليم الدولة', 'أما الفضاء الخارجي فخارج سيادة الدول', 'الفضاء الخارجي خارج سيادة الدول ولا يتملك (معاهدة 1967).'),
 8: (0, 'الاشتراك والإقليمية', 'يستوي الفاعل والشريك', 'إذا وقعت الجريمة كلها أو بعضها في الإقليم يستوي الفاعل والشريك، ولو مارس الشريك نشاطه خارج البلاد.'),
 9: (0, 'شروط الإقليمية', 'وقوع الجريمة كلها أو جزء منها في إقليم الدولة', 'شرط الإقليمية: وقوع الجريمة كلها أو جزء منها في إقليم الدولة.'),
 10: (0, 'رفع الدعوى', 'لا تقام الدعوى العمومية على مرتكب جريمة أو فعل في الخارج', 'م4: لا تقام الدعوى عن الجرائم الواقعة في الخارج إلا من النيابة العمومية، ويُمنع الادعاء المباشر.'),
 11: (0, 'الحصانات', 'إلا الحصانات التي يقررها القانون الدولي', 'يقرر الشرح أن الأصل لا يخرج عنه داخل الإقليم إلا الحصانات التي يقررها القانون الدولي (ومنها حصانة الممثلين الدبلوماسيين).'),
 12: (0, 'مبدأ الإقليمية', 'يطبق قانون العقوبات على كل جريمة تقع في إقليم الدولة', 'الأصل: يطبق قانون العقوبات على كل جريمة تقع في الإقليم أيا كانت جنسية الجاني أو المجني عليه.'),
 13: (0, 'الاشتراك والإقليمية', 'أن يشكل فعل الشريك جريمة أصلية مستقلة في مصر', 'الاستثناء الأول: أن يشكل فعل الشريك جريمة أصلية مستقلة في مصر، كحيازة سلاح بلا ترخيص.'),
 14: (0, 'مبدأ العلم', 'تسري القوانين الجنائية الوطنية على ما يقع من جرائم فوق السفن التي تحمل علم الدولة', 'مبدأ العلم: تسري القوانين الجنائية الوطنية على ما يقع فوق السفن التي تحمل علم الدولة.'),
 15: (0, 'مبدأ العينية', 'ولو كان الفعل غير معاقب عليه في البلد الذي وقع فيه', 'في العينية يعاقب الفاعل ولو كان الفعل غير معاقب عليه في البلد الذي وقع فيه.'),
 16: (0, 'مبدأ العينية', 'طائفة من الجرائم المرتكبة في الخارج أيا كانت جنسية فاعلها', 'العينية: يسري القانون على طائفة من الجرائم المرتكبة في الخارج أيا كانت جنسية فاعلها لأنها تمس مصالح أساسية للدولة.'),
 17: (0, 'أثر الحكم الأجنبي', 'في الجرائم التي يسري عليها مبدأ العينية', 'من استثناءات أثر البراءة الأجنبية جرائم العينية، إذ لا يلزم أن يعاقب القانون الأجنبي على الفعل.'),
 18: (0, 'مكان وقوع الجريمة', 'أو إذا وقع النشاط في الخارج والنتيجة في مصر', 'تقع الجريمة جزئيًا في مصر إذا وقع النشاط في الخارج والنتيجة في مصر، فتنطبق الإقليمية ولو لم يكن الجاني في مصر.'),
 19: (0, 'مبدأ العينية', 'جناية تزوير مما نص عليه في المادة 206', 'م2/ثانيا: من العينية: الجناية المخلة بأمن الحكومة، وتزوير م206، وتقليد العملة المتداولة قانونا في مصر.'),
 20: (1, 'الاشتراك والإقليمية', 'الرأي أنه لا يختص القضاء المصري بمحاكمة الشريك', 'الرأي أنه لا يختص القضاء المصري بمحاكمة الشريك، لأن مناط الاختصاص بالاشتراك هو الاختصاص بالفاعل الأصلي، وقد انتفى الاستثناءان.'),
 21: (0, 'الشخصية الإيجابية', 'لا يسري القانون إلا إذا كان الفعل معاقبا عليه في قانون البلد الذي وقع فيه', 'يشترط لسريان الشخصية الإيجابية أن يكون الفعل معاقبًا عليه في قانون البلد الذي وقع فيه.'),
}
out, bad = [], 0
for r in raw:
    n = int(r['n']); ans, prin, anc, exp = K[n]
    cnt = sum(btext(b).count(norm(anc)) for b in blocks)
    if cnt != 1: print('!! المرساة في س%d وردت %d مرة: %s' % (n, cnt, anc)); bad += 1
    if r['kind'] == 'tf': opts, typ = ['صح', 'خطأ'], 'tf'
    elif r['kind'] == 'yesno': opts, typ = ['نعم', 'لا'], 'tf'
    else: opts, typ = r['options'], 'mcq'
    out.append({'id': 'q-%03d' % n, 'type': typ, 'anchor': anc, 'principle': prin, 'text': r['text'], 'options': opts, 'correct': ans, 'explanation': exp, 'answerStatus': 'derived-from-text'})
json.dump({'bookId': 'madar-penal-territoriality', 'version': 1, 'questions': out}, open(ROOT + '/questions/madar-penal-territoriality.json', 'w', encoding='utf8'), ensure_ascii=False, indent=1)
print('أسئلة', len(out), 'مراسٍ مخالفة', bad, '| صح:', sum(1 for q in out if q['type'] == 'tf' and q['correct'] == 0), 'خطأ:', sum(1 for q in out if q['type'] == 'tf' and q['correct'] == 1))
